import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.Co1PSFSm.js";const g=JSON.parse('{"title":"Equivalents Management","description":"","frontmatter":{},"headers":[],"relativePath":"docs/equivalents.md","filePath":"docs/equivalents.md"}'),r={name:"docs/equivalents.md"};function o(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="equivalents-management" tabindex="-1">Equivalents Management <a class="header-anchor" href="#equivalents-management" aria-label="Permalink to &quot;Equivalents Management&quot;">​</a></h1><p>The <strong>Equivalents Management</strong> view is the control center for your transcription analysis. This is where you establish the formal link between an abstract musical concept (the transcription pattern) and its physical identifier (the Ref ID).</p><h2 id="understanding-the-table" tabindex="-1">Understanding the Table <a class="header-anchor" href="#understanding-the-table" aria-label="Permalink to &quot;Understanding the Table&quot;">​</a></h2><p>When you open the Equivalents view, you will see a large data table.</p><ul><li><strong>Pattern</strong>: The transcription data sequence (e.g., a Volpiano string like <code>1---c--d---3</code>).</li><li><strong>Occurrences</strong>: How many times this exact pattern appears across all your loaded transcription datasets.</li><li><strong>Global ID</strong>: The project-wide Reference ID assigned to this pattern.</li><li><strong>Local IDs</strong>: A list of manuscript-specific overrides, if any.</li><li><strong>Notes</strong>: A text field for your personal observations about this pattern.</li></ul><h2 id="assigning-global-ids" tabindex="-1">Assigning Global IDs <a class="header-anchor" href="#assigning-global-ids" aria-label="Permalink to &quot;Assigning Global IDs&quot;">​</a></h2><p>To categorize a new pattern:</p><ol><li>Locate a pattern you want to categorize in the table. You can use the search bar to filter for specific strings.</li><li>Click into the <strong>Global ID</strong> cell for that row.</li><li>Type your chosen Reference ID (e.g., <code>25</code>, <code>14a</code>).</li><li>Press <code>Enter</code> or click outside the cell to save.</li></ol><p>The tool will now associate every occurrence of that pattern with that Ref ID across all manuscripts (unless overridden).</p><h2 id="managing-local-overrides" tabindex="-1">Managing Local Overrides <a class="header-anchor" href="#managing-local-overrides" aria-label="Permalink to &quot;Managing Local Overrides&quot;">​</a></h2><p>Sometimes a specific manuscript writes a standard musical gesture in a non-standard way. You can document this using a Local Override.</p><ol><li>Click the <code>+</code> or edit icon in the <strong>Local IDs</strong> column for a specific pattern.</li><li>A modal will appear allowing you to select a specific manuscript from your directory.</li><li>Enter the overriding Ref ID for that specific manuscript.</li><li>Save the change.</li></ol><p>Now, whenever you encounter that pattern in that specific manuscript, it will be labeled with the Local ID instead of the Global ID.</p><h2 id="filtering-and-searching" tabindex="-1">Filtering and Searching <a class="header-anchor" href="#filtering-and-searching" aria-label="Permalink to &quot;Filtering and Searching&quot;">​</a></h2><p>The search bar at the top of the table allows you to quickly find patterns.</p><ul><li>You can search by the pattern string itself to find related musical gestures.</li><li>You can search by Ref ID to see all patterns assigned to a specific graphical shape.</li></ul>',16)])])}const p=a(r,[["render",o]]);export{g as __pageData,p as default};
